const body = $input.first().json.body;
const required = ['customer_message', 'customer_email'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.customer_message.trim().length < 10) return [{ json: { valid: false, error: 'customer_message too short' } }];
const ticketId = body.ticket_id || `TKT-${Date.now()}`;
return [{ json: {
  valid: true,
  ticketId,
  customerEmail: body.customer_email.trim(),
  customerName: body.customer_name || '',
  customerId: body.customer_id || '',
  customerPlan: body.customer_plan || '',
  customerMessage: body.customer_message.trim().slice(0, 3000),
  channel: body.channel || 'email',
  product: body.product || '',
  previousTicketCount: parseInt(body.previous_ticket_count) || 0,
  accountValue: parseFloat(body.account_value) || null,
  currency: body.currency || 'USD',
  knowledgeBase: (body.knowledge_base_snippets || []).slice(0, 5),
  teamSlackChannel: body.team_slack_channel || null,
  submittedAt: new Date().toISOString()
} }];

values.content:
Triage this support ticket.

Ticket ID: {{ $json.ticketId }}
Customer: {{ $json.customerName || 'unknown' }} ({{ $json.customerEmail }})
Customer ID: {{ $json.customerId || 'unknown' }}
Plan/tier: {{ $json.customerPlan || 'unknown' }}
Account value: {{ $json.accountValue ? $json.currency + $json.accountValue : 'unknown' }}
Channel: {{ $json.channel }}
Product: {{ $json.product || 'not specified' }}
Previous tickets this account: {{ $json.previousTicketCount }}

Customer message:
{{ $json.customerMessage }}

Knowledge base snippets available:
{{ $json.knowledgeBase.map((kb, i) => `${i+1}. ${kb}`).join('\n') || 'none provided' }}

Return this JSON:
{
  "issue_category": "one of: billing | technical_bug | feature_request | how_to | account_access | complaint | cancellation | data_question | integration | other",
  "issue_summary": "1-2 sentence plain-language summary of what the customer actually needs",
  "urgency": "one of: critical | high | medium | low",
  "urgency_rationale": "one sentence — why this urgency level",
  "sentiment": "one of: very_negative | negative | neutral | positive",
  "escalation_needed": true or false,
  "escalation_reason": "why escalation is needed — null if not needed",
  "routing": "one of: tier1_support | tier2_technical | billing_team | account_management | engineering | product_team | legal",
  "routing_rationale": "why this team",
  "sla_recommendation": "specific time window e.g. respond within 2 hours",
  "draft_response": "complete first response to send to the customer — professional, specific to their issue, directly helpful. References the knowledge base if relevant. Addresses any emotional tone. Ends with a clear next step or resolution. Signed off professionally.",
  "internal_note": "2-3 sentences for the support agent — what to watch for, context about the account, any flags",
  "churn_risk": "one of: high | medium | low | none",
  "churn_risk_rationale": "why this churn risk level — null if none"
}

