const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let triage;
try { triage = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
triage._ticket = {
  ticketId: input.ticketId,
  customerEmail: input.customerEmail,
  customerName: input.customerName,
  customerId: input.customerId,
  customerPlan: input.customerPlan,
  accountValue: input.accountValue,
  currency: input.currency,
  channel: input.channel,
  product: input.product,
  previousTicketCount: input.previousTicketCount,
  customerMessage: input.customerMessage,
  teamSlackChannel: input.teamSlackChannel,
  submittedAt: input.submittedAt
};
return [{ json: triage }];
